pub(crate) fn t_zeros(mut b: &mut crate::port::Buf, n: i32) -> i32 {
    // The caller's part of `cc-decode`'s contract: `n` zero bytes to paint on.
    let mut i: i32 = 0;
    while i < n {
        crate::port::buf_push(b, 0);
        i += 1;
    }
    return 0;
}
pub(crate) fn t_strip(emon_t: i32, t: &[u8], k: i32, flags: i32, out: &mut crate::port::Buf, msg: &str) -> i32 {
    // Decode the one strip of a 48 x 36 bilevel fixture; the status of the decoder.
    let r: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let s: i32 = tc_check(t, 0, 1, r);
    crate::testport::assert_eq(s, 0, msg);
    crate::testport::assert_eq(crate::port::cells_at(r, tr_nchunks()), 1, msg);
    let off: i32 = crate::port::cells_at(r, crate::port::cells_at(r, tr_offs_at()));
    let n: i32 = crate::port::cells_at(r, crate::port::cells_at(r, tr_lens_at()));
    t_zeros(out, 216);
    return cc_decode(t, off, off + n, k, 48, 36, flags, out, ws);
}
pub(crate) fn t_same(emon_t: i32, t: &[u8], k: i32, none: &[u8], msg: &str) -> i32 {
    // The strip of `t` decoded is the picture the uncompressed file `none` holds, bit for bit (libtiff reads a CCITT black run as 1 bits whatever the photometric: D188).
    let got: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let r: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let s: i32 = tc_check(none, 0, 1, r);
    let off: i32 = crate::port::cells_at(r, crate::port::cells_at(r, tr_offs_at()));
    let mut i: i32 = 0;
    crate::testport::assert_eq(t_strip(emon_t, t, k, 0, got, msg), 0, msg);
    crate::testport::assert_eq(s, 0, msg);
    crate::testport::assert_eq(crate::port::buf_len(got), 216, msg);
    while i < 216 {
        crate::testport::assert_eq(crate::port::buf_at(got, i), crate::port::blob_u8(none, off + i), msg);
        i += 1;
    }
    return 0;
}
#[test]
fn test_ccitt_decodes_the_tiff_fixtures() {
    t_same(0, &crate::testport::test_file("image/tiff-bilevel-g4.tif")[..], -1, &crate::testport::test_file("image/tiff-bilevel-none.tif")[..], "Group 4");
    t_same(0, &crate::testport::test_file("image/tiff-bilevel-g3.tif")[..], 0, &crate::testport::test_file("image/tiff-bilevel-none.tif")[..], "Group 3, one-dimensional");
}
pub(crate) fn t_raw_strip(emon_t: i32, t: &[u8], off: i32, k: i32, none: &[u8], msg: &str) -> i32 {
    // A refused TIFF (validator says no) whose strip starts at `off` and runs to the end of the strips: the decoder reads
    // what the validator will not hand over: Group 3 two-dimensional, and EOLs padded with fill bits.
    let got: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let r: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let s: i32 = tc_check(none, 0, 1, r);
    let woff: i32 = crate::port::cells_at(r, crate::port::cells_at(r, tr_offs_at()));
    let mut i: i32 = 0;
    crate::testport::assert_eq(s, 0, msg);
    t_zeros(got, 216);
    crate::testport::assert_eq(cc_decode(t, off, crate::port::blob_len(t), k, 48, 36, 0, got, ws), 0, msg);
    crate::testport::assert_eq(crate::port::buf_len(got), 216, msg);
    while i < 216 {
        crate::testport::assert_eq(crate::port::buf_at(got, i), crate::port::blob_u8(none, woff + i), msg);
        i += 1;
    }
    return 0;
}
#[test]
fn test_ccitt_reads_what_the_validator_refuses() {
    t_raw_strip(0, &crate::testport::test_file("image/tiff-bilevel-g3-2d.tif")[..], 8, 1, &crate::testport::test_file("image/tiff-bilevel-none.tif")[..], "Group 3, two-dimensional");
    t_raw_strip(0, &crate::testport::test_file("image/tiff-bilevel-g3-fill.tif")[..], 8, 0, &crate::testport::test_file("image/tiff-bilevel-none.tif")[..], "Group 3 with fill bits before the EOLs");
}
#[test]
fn test_exif_reader() {
    // The first directory of an EXIF blob: orientation 1..8 and the two resolutions; anything else says (1, 0, 0).
    let r: &mut crate::port::Cells = &mut crate::port::Cells::new();
    tc_exif(&crate::testport::hex_blob("49492a000800000004001201030001000000060000001a010500010000003e0000001b010500010000003e000000280103000100000002000000000000002c01000001000000")[..], 0, 70, r);
    crate::testport::assert_eq(crate::port::cells_at(r, tr_eo()), 6, "orientation");
    crate::testport::assert_eq(crate::port::cells_at(r, tr_ex()), 30000, "horizontal resolution");
    crate::testport::assert_eq(crate::port::cells_at(r, tr_ey()), 30000, "vertical resolution");
    tc_exif(&crate::testport::hex_blob("010203040549492a000800000004001201030001000000060000001a010500010000003e0000001b010500010000003e000000280103000100000002000000000000002c01000001000000")[..], 5, 70, r);
    crate::testport::assert_eq(crate::port::cells_at(r, tr_eo()), 6, "orientation, in a blob that starts later");
    crate::testport::assert_eq(crate::port::cells_at(r, tr_ex()), 30000, "... and its resolution");
    tc_exif(&crate::testport::hex_blob("49492a000800000004001201030001000000010000001a010500010000003e0000001b010500010000003e000000280103000100000002000000000000009600000001000000")[..], 0, 70, r);
    crate::testport::assert_eq(crate::port::cells_at(r, tr_eo()), 1, "orientation 1");
    crate::testport::assert_eq(crate::port::cells_at(r, tr_ex()), 15000, "150 dpi");
    tc_exif(&crate::testport::hex_blob("4d4d002b00080000")[..], 0, 8, r);
    crate::testport::assert_eq(crate::port::cells_at(r, tr_eo()), 1, "BigTIFF says nothing");
    crate::testport::assert_eq(crate::port::cells_at(r, tr_ex()), 0, "... of the resolution");
    tc_exif(&crate::testport::hex_blob("49492a00")[..], 0, 4, r);
    crate::testport::assert_eq(crate::port::cells_at(r, tr_eo()), 1, "a blob of four bytes says nothing");
    tc_exif(&crate::testport::hex_blob("49492a00ffffffff0000")[..], 0, 10, r);
    crate::testport::assert_eq(crate::port::cells_at(r, tr_eo()), 1, "a directory outside the blob says nothing");
    crate::testport::assert_eq(crate::port::cells_at(r, tr_ey()), 0, "... of the resolution");
}
